steps.command:
# Web UI: Navigate to Grafana Explore → Select Loki → Query: {cluster_id="$CLUSTER_ID",namespace="metrics-test"} |= "$LOG_MARKER"

# Or via API:
curl -H "Authorization: Bearer $GRAFANA_TOKEN" \
  -H "Content-Type: application/json" \
  -X POST "$GRAFANA_URL/api/ds/query" \
  -d '{
    "queries": [
      {
        "refId": "A",
        "expr": "{cluster_id=\"'"$CLUSTER_ID"'\",namespace=\"metrics-test\"} |= \"'"$LOG_MARKER"'\""  ,
        "datasourceId": 2
      }
    ],
    "from": "now-30m",
    "to": "now"
  }' | jq

export HC_API_URL=$(oc get hostedcluster -n $HC_NAMESPACE $TEST_CLUSTER_NAME -o jsonpath='{.status.controlPlaneEndpoint.host}')
echo "HostedCluster API URL: $HC_API_URL"
echo "Expected API URL: $CLUSTER_API_URL"
